import { useState, useEffect } from 'react';
import { useHistory } from 'react-router-dom';

function LoginDetails() {
    const [username, setUsername] = useState('');
    const [firstName, setFirstName] = useState('');
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [isSignup, setIsSignup] = useState(false);
    const [errorMessage, setErrorMessage] = useState('');
    const history = useHistory();

    useEffect(() => {
        const token = localStorage.getItem('token');
        if (token) {
            history.push('/profile');
        }
    }, [history]);


    const handleSubmit = (e) => {
        e.preventDefault();
        const endpoint = isSignup ? 'http://localhost:3001/signup' : 'http://localhost:3001/login';
        fetch(endpoint, {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({email, password})
        })
        .then(response => {
            if (!response.ok) {
                return response.text().then(text => { throw new Error(text) });
            }
            return response.json();
        })
        .then(data => {
            const userId = data.userId;
            const token = data.token;
            localStorage.setItem('userId', userId);
            localStorage.setItem('token', token);
            history.push('/profile');
        })
        .catch(error => {
            console.error('Erreur lors de la connexion', error);
            setErrorMessage(error.message);
        });
    }

    return (
        <div className="login-page">
            <div className="login-card">
                <h2 className="login-title">{isSignup ? 'Inscription' : 'Connexion'}</h2>
                
                {errorMessage && <p className="error-message">{errorMessage}</p>}
                
                <form className="login-form" onSubmit={handleSubmit}>
                    {/* Ces champs n'apparaissent qu'à l'inscription */}
                    {isSignup && (
                        <>
                            <input className="form-input" type="text" placeholder="Nom" value={username} onChange={(e) => setUsername(e.target.value)} required />
                            <input className="form-input" type="text" placeholder="Prénom" value={firstName} onChange={(e) => setFirstName(e.target.value)} required />
                        </>
                    )}
                    
                    <input className="form-input" type="email" placeholder="Email" value={email} onChange={(e) => setEmail(e.target.value)} required />
                    <input className="form-input" type="password" placeholder="Mot de passe" value={password} onChange={(e) => setPassword(e.target.value)} required />
                    
                    {isSignup && (
                        <input className="form-input" type="password" placeholder="Confirmer le mot de passe" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} required />
                    )}
                    
                    <button className="btn-primary" type="submit">
                        {isSignup ? "S'inscrire" : 'Se connecter'}
                    </button>
                </form>

                <div className="toggle-section">
                    <p className="toggle-text">
                        {isSignup ? 'Vous avez déjà un compte ?' : "Vous n'avez pas de compte ?"}
                    </p>
                    <button className="btn-secondary" onClick={() => {setIsSignup(!isSignup); setErrorMessage('');}}>
                        {isSignup ? 'Se connecter' : "S'inscrire"}
                    </button>
                </div>
            </div>
        </div>
    );

}
export default LoginDetails;
